/*
 * WHAT DENO PROVIDES, as far as `tsc` needs to know (openspec: typescript-throughout). The Edge Functions run in Deno,
 * and tsconfig.functions.json checks them with tsc: Deno's globals and its URL imports read as any here.
 */
declare const Deno: any
declare const EdgeRuntime: any
/* the packages the workspace installs read as themselves */
declare module 'npm:@supabase/supabase-js@2' { export * from '@supabase/supabase-js' }
declare module 'jsr:@supabase/supabase-js@2' { export * from '@supabase/supabase-js' }
declare module 'npm:*'
declare module 'jsr:*'
declare module 'https://*'
declare module 'node:*'
/* what build/assemble.mjs generates into the functions, and the bare names their import maps resolve */
declare module '*/_shared/agents/loop.js'
declare module '*/_shared/agents/model.js'
declare module '*/_shared/analytics.json'
declare module '*/_shared/bots.json'
declare module '*/_shared/commands.json'
declare module '*/_shared/emails/strings.json'
declare module '*/_shared/forms.json'
declare module '*/_shared/pipe/build/admin-pipe.mjs'
declare module '*/_shared/pipe/build/assets.mjs'
