/* generated by assemble (build/payment-provider-registry.mts): the site's provider, made from its secrets, or a throw */
declare module '*/payment-provider-registry.ts' {
  import type { PaymentProviderAdapter } from './_shared/payment-provider.mts'
  export const SITE_PAYMENT_PROVIDER_ID: string
  export function createSitePaymentProvider(secrets: Readonly<Record<string, string | undefined>>, runtime?: { stripe?: unknown, fetch?: typeof fetch }): Promise<PaymentProviderAdapter>
}
declare module '*/pipe/build/admin-pipe.mjs'
declare module '*/pipe/build/admin-schemas.mjs'
declare module '*/pipe/build/assets.mjs'
declare module '*/pipe/build/models/index.mjs'
